-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where coalesce(mantra_translit, '') like '%gum%';
  if n <> 0 then raise exception '% roman mantra(s) still say gum', n; end if;

  -- Scoped by name. An unscoped count of roman containing gm would also
  -- match any ordinary g followed by m, which is not what is being asserted.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and step_title_en in ('Naivedyam', 'Avahanam — Vinayaka', 'Karpura Neerajanam', 'Dhoopam & Deepam')
     and mantra_translit like '%gm%';
  if n <> 4 then raise exception 'only % of the 4 step(s) say gm', n; end if;

  -- The Tamil was NOT touched, and the Devanagari still carries the sign.
  select count(*) into n from public.pooja_steps
   where mantra_tamil like '%கும்%' and pooja_id = 'nitya_panchayatana';
  if n < 4 then raise exception 'the Tamil lost கும்: only % row(s) keep it', n; end if;

  select count(*) into n from public.pooja_steps
   where coalesce(mantra_sanskrit, '') like '%ꣳ%';
  if n <> 4 then raise exception 'expected 4 step(s) to keep the sign in Devanagari, found %', n; end if;
end $$;


